 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # The scattered singleton color marks the anchor locations.
    marker_color = None
    best = 0
    for color, n in counts.items():
        if color == background or n < 2:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        isolated = all(
            not any((dr or dc) and 0 <= r+dr < h and 0 <= c+dc < w
                    and grid[r+dr][c+dc] == color
                    for dr in (-1, 0, 1) for dc in (-1, 0, 1))
            for r, c in cells
        )
        if isolated and n > best:
            marker_color, best = color, n
    if marker_color is None:
        return [row[:] for row in grid]

    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]
    # Extract the contiguous exemplar, excluding background and anchors.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] not in (background, marker_color)}
    components = []
    while remaining:
        start = remaining.pop()
        comp = [start]
        q = [start]
        while q:
            r, c = q.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r+dr, c+dc)
                    if p in remaining:
                        remaining.remove(p)
                        comp.append(p)
                        q.append(p)
        components.append(comp)
    if not components:
        return [row[:] for row in grid]
    shape = max(components, key=len)
    minr = min(r for r, c in shape); maxr = max(r for r, c in shape)
    minc = min(c for r, c in shape); maxc = max(c for r, c in shape)
    ar, ac = (minr + maxr)//2, (minc + maxc)//2
    offsets = [(r-ar, c-ac, grid[r][c]) for r, c in shape]

    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr, dc, value in offsets:
            rr, cc = mr+dr, mc+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
